                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.DANIEL_KLEIN_DB_AMAZON_VENDOR_PARTNER_SALES AS SELECT \'AMAZON VC\' AS MARKETPLACE, \'AMAZON VC\' AS CHANNEL, \'AMAZON VC\' AS SOURCE, CONCAT( ASIN, TO_DATE(STARTDATE), ORDEREDUNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING), TO_DATE(ENDDATE) ) AS ORDER_ID, CONCAT( ASIN, TO_DATE(STARTDATE), ORDEREDUNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING), TO_DATE(ENDDATE) ) AS REFERENCE_CODE, CONCAT( ASIN, TO_DATE(STARTDATE), ORDEREDUNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING), TO_DATE(ENDDATE) ) AS SALEORDERITEMCODE, CONCAT( ASIN, TO_DATE(STARTDATE), ORDEREDUNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING), TO_DATE(ENDDATE) ) AS SALES_ORDER_ITEM_ID, ASIN::STRING AS ASIN, STARTDATE::TIMESTAMP AS STARTTIME, ENDDATE::TIMESTAMP AS ENDTIME, ORDEREDUNITS::NUMBER AS ORDERED_UNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING) AS ORDERED_REVENUE, SHIPPEDUNITS::NUMBER AS SHIPPEDUNITS, CUSTOMERRETURNS::NUMBER AS CUSTOMERRETURNS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING) / NULLIF(ORDEREDUNITS::NUMBER, 0) * CUSTOMERRETURNS::NUMBER AS RETURNED_REVENUE, NULL AS AMAZON_VC_SKU, NULL AS MASTER_SKU, NULL AS PRODUCT_NAME, NULL AS CATEGORY, NULL AS BRAND, NULL AS PRODUCT, NULL AS PACK_TYPE, Upper(trim(gs.CATALOG_NAME)) as mapped_product_name, Upper(trim(gs.PRODUCT_CATEGORY)) as mapped_category, Upper(trim(gs.PRODUCT_SUB_CATEGORY)) as mapped_sub_category, Upper(trim(gs.master_sku)) as commonsku, upper(trim(gs.BUCKET_1)) as bucket_1, upper(trim(gs.BUCKET_2)) as bucket_2, (TRY_CAST(gs.MRP as INT) * ORDEREDUNITS::NUMBER) as sku_mrp FROM MAPLEMONK.DANIEL_KLEIN_Amazon_or_vendor_GET_VENDOR_SALES_REPORT FI LEFT JOIN ( SELECT * FROM DANIEL_KLEIN_DB.MAPLEMONK.Google_Sheet_SKU_MASTER where amazon_sku <> \'0\' QUALIFY ROW_NUMBER() OVER (PARTITION BY AMAZON_SKU ORDER BY MASTER_SKU) = 1 ) gs ON TRIM(upper(fi.asin)) = TRIM(upper(gs.amazon_sku)) ;",
                    "transaction": true
                }
